c='p2';B='CSDL 1'
S=[]
S.append(TITLE('TIN HỌC · CƠ SỞ DỮ LIỆU 1','CƠ SỞ DỮ LIỆU VÀ<br>HỆ QUẢN TRỊ CSDL','Khái niệm CSDL, bảng – bản ghi – trường, hệ quản trị CSDL, mô hình quan hệ, lợi ích.',['CSDL','HQTCSDL','bảng','bản ghi','trường']))
S.append(goals(c,B,['Giải thích <b>CSDL</b> và <b>hệ quản trị CSDL</b>.','Nhận biết <b>bảng, bản ghi, trường</b> trong CSDL quan hệ.','Nêu <b>chức năng</b> của hệ QTCSDL.','Nêu <b>lợi ích</b> so với lưu trữ tệp rời rạc.','Phân biệt <b>người dùng</b> các vai trò: quản trị, lập trình, cuối.'],['Dữ liệu và CSDL','Mô hình quan hệ','Hệ quản trị CSDL','Lợi ích, ứng dụng','Trọng tâm, HSG']))
S.append(S2(c,B+' · 1','Dữ liệu và thông tin',card('Phân biệt',ul(['<b>Dữ liệu</b>: các giá trị thô (số, chữ, ảnh) chưa qua xử lí.','<b>Thông tin</b>: dữ liệu được <b>xử lí</b> để có ý nghĩa.','Ví dụ: điểm 8, 7, 9 là dữ liệu; “điểm trung bình lớp là 8” là thông tin.'],6)),KEY('<b>Cơ sở dữ liệu (CSDL)</b> là tập hợp dữ liệu <b>có tổ chức</b>, có liên quan, lưu trên thiết bị nhớ để <b>nhiều người, nhiều ứng dụng</b> cùng khai thác.')+OK('Ví dụ: CSDL thư viện, CSDL học sinh, CSDL bán hàng, CSDL ngân hàng.')))
S.append(S2(c,B+' · 1','Vì sao cần CSDL? Lưu trữ bằng tệp rời rạc',card('Nhược điểm của quản lí bằng tệp',ul(['<b>Dư thừa, trùng lặp</b> dữ liệu (cùng thông tin ở nhiều nơi).','Dễ <b>mâu thuẫn</b>: sửa chỗ này quên chỗ kia.','<b>Khó truy xuất</b> theo nhiều tiêu chí.','Khó <b>chia sẻ</b>, <b>bảo mật</b>, sao lưu.'],6)),KEY('CSDL giải quyết: dữ liệu <b>tập trung, nhất quán, ít dư thừa</b>, có <b>phân quyền</b>, truy vấn bằng <b>ngôn ngữ chuẩn (SQL)</b>.')))
S.append(S2(c,B+' · 2','Mô hình CSDL quan hệ',card('Các khái niệm',ul(['<b>Bảng</b> (table): dữ liệu theo <b>hàng và cột</b>.','<b>Bản ghi</b> (record, hàng): một đối tượng cụ thể.','<b>Trường</b> (field, cột): một thuộc tính, có <b>kiểu dữ liệu</b>.','<b>Khoá chính</b>: trường nhận diện duy nhất mỗi bản ghi.'],6)),RES(OUT(SQLRUN(SETUP,'SELECT * FROM hocsinh'),24),'Bảng HOCSINH (6 bản ghi, 5 trường)')))
S.append(S2(c,B+' · 2','Sơ đồ bảng, bản ghi, trường',RES('<svg viewBox="0 0 520 280" style="width:100%"><g font-family="sans-serif" font-weight="800" font-size="22" text-anchor="middle"><rect x="10" y="20" width="500" height="44" fill="#00838F"/><g fill="#fff"><text x="70" y="50">MAHS</text><text x="185" y="50">HOTEN</text><text x="295" y="50">LOP</text><text x="405" y="50">DIEMTB</text></g><g fill="#E0F7FA" stroke="#00838F" stroke-width="2"><rect x="10" y="64" width="500" height="44"/><rect x="10" y="108" width="500" height="44" fill="#FFF59D"/><rect x="10" y="152" width="500" height="44"/></g><g fill="#0B2545"><text x="70" y="94">HS01</text><text x="185" y="94">An</text><text x="295" y="94">12A</text><text x="405" y="94">8.5</text><text x="70" y="138">HS02</text><text x="185" y="138">Binh</text><text x="295" y="138">12A</text><text x="405" y="138">7.0</text><text x="70" y="182">HS03</text><text x="185" y="182">Chi</text><text x="295" y="182">12B</text><text x="405" y="182">9.0</text></g></g><text x="260" y="238" text-anchor="middle" font-size="22" font-weight="800" fill="#C62828">hàng vàng = 1 bản ghi (HS02); tiêu đề cột = trường</text><text x="260" y="268" text-anchor="middle" font-size="22" font-weight="800" fill="#00838F">MAHS là khoá chính: không trùng nhau</text></svg>','Minh hoạ'),card('Quy ước',ul(['Cột = <b>trường</b> (thuộc tính).','Hàng = <b>bản ghi</b> (bộ).','Mỗi ô chứa <b>một giá trị</b> (không lặp).'],6))))
S.append(TB(c,B+' · 2','Tính chất của bảng trong mô hình quan hệ',['Tính chất','Ý nghĩa'],[['Tên bảng','<b>duy nhất</b> trong CSDL'],['Tên trường','<b>duy nhất</b> trong một bảng'],['Giá trị mỗi ô','<b>nguyên tử</b>: một giá trị, không phải danh sách'],['Thứ tự','thứ tự hàng, cột <b>không quan trọng</b>'],['Hai bản ghi','<b>không trùng hoàn toàn</b> (có khoá chính)']],note=KEY('Dữ liệu một ô ghi nhiều số điện thoại cách nhau dấu phẩy <b>vi phạm</b> tính nguyên tử; nên tách thành bảng riêng.')))
S.append(S2(c,B+' · 3','Hệ quản trị cơ sở dữ liệu (HQTCSDL)',card('Khái niệm',ul(['<b>Phần mềm</b> để <b>tạo, lưu trữ, cập nhật, truy xuất</b> và <b>quản lí</b> CSDL.','Là <b>trung gian</b> giữa người dùng/ứng dụng và dữ liệu.','Ví dụ: <b>MySQL, SQL Server, PostgreSQL, Oracle, SQLite, MS Access</b>.'],6)),RES('<svg viewBox="0 0 520 300" style="width:100%"><g font-family="sans-serif" font-weight="800" text-anchor="middle"><rect x="10" y="10" width="500" height="55" rx="10" fill="#B2EBF2" stroke="#00838F" stroke-width="3"/><text x="260" y="46" font-size="24" fill="#0B2545">Người dùng, ứng dụng web / di động</text><path d="M260 66 L260 105 M245 92 L260 108 L275 92" stroke="#00838F" stroke-width="5" fill="none"/><rect x="10" y="110" width="500" height="70" rx="10" fill="#00838F"/><text x="260" y="143" font-size="26" fill="#fff">HỆ QUẢN TRỊ CSDL</text><text x="260" y="170" font-size="20" fill="#E0F7FA">(MySQL, SQL Server, SQLite…)</text><path d="M260 182 L260 220 M245 207 L260 223 L275 207" stroke="#00838F" stroke-width="5" fill="none"/><ellipse cx="260" cy="255" rx="160" ry="35" fill="#FFE082" stroke="#E65100" stroke-width="3"/><text x="260" y="263" font-size="24" fill="#0B2545">CƠ SỞ DỮ LIỆU</text></g></svg>','Mô hình ba lớp')))
S.append(TB(c,B+' · 3','Chức năng của hệ QTCSDL',['Chức năng','Nội dung'],[['<b>Định nghĩa dữ liệu</b>','tạo bảng, kiểu dữ liệu, khoá, ràng buộc (<b>DDL</b>: CREATE, ALTER, DROP)'],['<b>Thao tác dữ liệu</b>','thêm, sửa, xoá, truy vấn (<b>DML</b>: INSERT, UPDATE, DELETE, SELECT)'],['<b>Kiểm soát, điều khiển</b>','phân quyền, bảo mật, toàn vẹn, đồng thời, sao lưu, phục hồi (<b>DCL</b>: GRANT, REVOKE)']],note=KEY('Ba nhóm lệnh SQL tương ứng ba chức năng: <b>DDL, DML, DCL</b>.')))
S.append(PYR(c,B+' · 3','Ví dụ DDL và DML bằng SQL','import sqlite3\ncon = sqlite3.connect(":memory:")\ncon.execute("CREATE TABLE sv(ma INTEGER PRIMARY KEY, ten TEXT)")\ncon.execute("INSERT INTO sv VALUES (1, \'An\')")\ncon.execute("INSERT INTO sv VALUES (2, \'Binh\')")\ncon.execute("UPDATE sv SET ten = \'Bình\' WHERE ma = 2")\ncon.execute("DELETE FROM sv WHERE ma = 1")\nprint(con.execute("SELECT * FROM sv").fetchall())',KEY('<b>CREATE</b> tạo bảng; <b>INSERT</b> thêm; <b>UPDATE</b> sửa; <b>DELETE</b> xoá; <b>SELECT</b> truy vấn. Python có sẵn mô-đun <b>sqlite3</b>.'),19,lab='Kết quả chạy'))
S.append(S2(c,B+' · 3','Các đối tượng người dùng CSDL',T(tr('Người dùng','Nhiệm vụ',h=True)+tr('<b>Quản trị CSDL</b>','thiết kế, cấp quyền, sao lưu, bảo mật, tối ưu')+tr('<b>Lập trình viên</b>','viết ứng dụng truy cập CSDL')+tr('<b>Người dùng cuối</b>','nhập, xem, tìm kiếm dữ liệu qua ứng dụng')),KEY('Người dùng cuối <b>không cần biết SQL</b>: họ dùng giao diện ứng dụng, ứng dụng gọi HQTCSDL.')+OK('Ví dụ: học sinh tra điểm trên website là <b>người dùng cuối</b>; giáo viên Tin viết trang tra điểm là <b>lập trình viên</b>.')))
S.append(S2(c,B+' · 4','Lợi ích của CSDL và hệ QTCSDL',card('Lợi ích',ul(['<b>Giảm dư thừa</b> và mâu thuẫn dữ liệu.','<b>Toàn vẹn</b>: dữ liệu đúng, đủ nhờ ràng buộc.','<b>Chia sẻ</b> nhiều người, nhiều ứng dụng.','<b>Bảo mật, phân quyền</b> truy cập.','<b>Truy vấn nhanh</b> theo nhiều tiêu chí.','Sao lưu, <b>phục hồi</b> khi sự cố.'],6)),KEY('Dùng CSDL tập trung thay cho tệp rời rạc giúp <b>dễ bảo trì, mở rộng</b> khi dữ liệu lớn.')))
S.append(TB(c,B+' · 4','So sánh tệp rời rạc và CSDL',['Tiêu chí','Tệp rời rạc','CSDL + HQTCSDL'],[['Dư thừa dữ liệu','cao','thấp'],['Nhất quán','dễ mâu thuẫn','đảm bảo bằng ràng buộc'],['Truy vấn phức tạp','phải tự viết chương trình','một câu SQL'],['Nhiều người dùng đồng thời','dễ xung đột','kiểm soát đồng thời'],['Bảo mật','theo tệp','theo người dùng, bảng, cột']],note=KEY('CSDL không chỉ là bảng tính: khác Excel ở <b>ràng buộc, nhiều người dùng, truy vấn chuẩn, khối lượng lớn</b>.')))
S.append(S2(c,B+' · 4','Ứng dụng thực tế của CSDL',card('Ví dụ',ul(['<b>Trường học</b>: học sinh, điểm, thời khoá biểu.','<b>Ngân hàng</b>: tài khoản, giao dịch.','<b>Thương mại điện tử</b>: sản phẩm, đơn hàng, khách.','<b>Bệnh viện</b>: hồ sơ bệnh án.','<b>Mạng xã hội</b>: người dùng, bài đăng, bạn bè.'],6)),KEY('Mỗi hệ thống thường có <b>nhiều bảng liên kết</b> với nhau bằng <b>khoá ngoài</b> (học ở bài sau).')))
S.append(S2(c,B+' · 4','Mô hình thực thể – liên kết (ERD) sơ lược',RES('<svg viewBox="0 0 520 240" style="width:100%"><g font-family="sans-serif" font-weight="800" text-anchor="middle" font-size="24"><rect x="10" y="85" width="180" height="70" fill="#B2EBF2" stroke="#00838F" stroke-width="4"/><text x="100" y="128" fill="#0B2545">HOCSINH</text><polygon points="260,70 320,120 260,170 200,120" fill="#FFF59D" stroke="#F9A825" stroke-width="4"/><text x="260" y="128" fill="#0B2545" font-size="20">học ở</text><rect x="330" y="85" width="180" height="70" fill="#B2EBF2" stroke="#00838F" stroke-width="4"/><text x="420" y="128" fill="#0B2545">LOP</text><path d="M190 120 L200 120 M320 120 L330 120" stroke="#0B2545" stroke-width="4"/><text x="196" y="105" font-size="22" fill="#C62828">N</text><text x="326" y="105" font-size="22" fill="#C62828">1</text></g><text x="260" y="215" text-anchor="middle" font-size="22" font-weight="800" fill="#00838F">Một lớp có nhiều học sinh; mỗi học sinh thuộc một lớp (1–N)</text></svg>','Sơ đồ'),card('Kí hiệu',ul(['<b>Hình chữ nhật</b>: thực thể (bảng).','<b>Hình thoi</b>: mối liên kết.','<b>1–N</b>: một – nhiều → khoá ngoài ở phía N.'],6))))
S+=END(c,B,['<b>CSDL</b>: dữ liệu có tổ chức, dùng chung; <b>HQTCSDL</b>: phần mềm quản lí CSDL.','<b>Bảng – bản ghi (hàng) – trường (cột)</b>; mỗi ô một giá trị.','Chức năng: <b>định nghĩa</b>, <b>thao tác</b>, <b>kiểm soát</b> dữ liệu.','Lợi ích: ít dư thừa, nhất quán, chia sẻ, bảo mật, truy vấn nhanh.','Người dùng: <b>quản trị</b>, <b>lập trình</b>, <b>cuối</b>.'],[('Phần mềm quản lí CSDL','HQTCSDL'),('Một hàng của bảng','bản ghi'),('Một cột của bảng','trường'),('Định danh duy nhất','khoá chính')],'CSDL khác HQTCSDL: CSDL là <b>dữ liệu</b>, HQTCSDL là <b>phần mềm</b>.',['Excel <b>không phải</b> HQTCSDL đầy đủ.','Một ô <b>nhiều giá trị</b> vi phạm mô hình quan hệ.','Thứ tự hàng/cột <b>không có ý nghĩa</b> trong bảng quan hệ.','Dữ liệu <b>dư thừa</b> là nguyên nhân gây mâu thuẫn khi cập nhật.'],['CSDL <b>NoSQL</b> (MongoDB, Redis): không dùng bảng.','<b>Kho dữ liệu</b> (data warehouse), <b>dữ liệu lớn</b>.','<b>Chuẩn hoá</b> (1NF, 2NF, 3NF): tránh dư thừa.'],
 [('Phân biệt CSDL và hệ quản trị CSDL.',),('Trong bảng HOCSINH ở slide trước, có mấy bản ghi, mấy trường?',),('Kể ba chức năng chính của hệ QTCSDL.',),('Nêu hai lợi ích của CSDL so với lưu trữ tệp rời rạc.',),('Ai là người dùng cuối trong hệ thống tra cứu điểm của trường?',)],
 [('<b>CSDL</b>: dữ liệu. <b>HQTCSDL</b>: phần mềm quản lí dữ liệu đó.',),('<b>6</b> bản ghi và <b>5</b> trường.',),('Định nghĩa dữ liệu; thao tác dữ liệu; kiểm soát, điều khiển truy cập.',),('Giảm dư thừa, mâu thuẫn; dễ chia sẻ và bảo mật; truy vấn nhanh.',),('<b>Học sinh, phụ huynh</b> vào tra điểm.',)],
 [('Ô “Điện thoại” của một học sinh ghi “0901, 0912”. Vi phạm tính chất nào của mô hình quan hệ? Đề xuất cách sửa.',),('Một công ty lưu địa chỉ khách hàng trong bảng DONHANG cho từng đơn. Hậu quả khi khách đổi địa chỉ? Nên thiết kế thế nào?',),('Đúng hay sai: (a) MySQL là một CSDL. (b) Thứ tự các cột trong bảng không quan trọng. (c) UPDATE thuộc nhóm DDL. (d) Một bảng có thể không có khoá chính nhưng khi đó khó phân biệt các bản ghi trùng.',),('Phân loại lệnh theo DDL/DML/DCL: CREATE TABLE, SELECT, GRANT, DELETE, ALTER TABLE, REVOKE.',),('Vẽ (mô tả) bảng LOP và HOCSINH, chỉ rõ trường nào là khoá ngoài.',),('Vì sao nói người dùng cuối không cần biết SQL?',)],
 [('Vi phạm tính <b>nguyên tử</b> của ô. Sửa: tách bảng <b>DIENTHOAI(mahs, sdt)</b>, mỗi dòng một số.',),('Phải sửa ở <b>nhiều đơn</b> (dư thừa); dễ mâu thuẫn. Nên tách bảng <b>KHACHHANG</b> (lưu địa chỉ một lần) và DONHANG chứa <b>makh</b> (khoá ngoài).',),('(a) <b>Sai</b>: MySQL là HQTCSDL. (b) <b>Đúng</b>. (c) <b>Sai</b>: UPDATE là DML. (d) <b>Đúng</b>.',),('DDL: CREATE TABLE, ALTER TABLE. DML: SELECT, DELETE. DCL: GRANT, REVOKE.',),('LOP(malop, tenlop, gvcn) và HOCSINH(mahs, hoten, <b>lop</b>, …): trường <b>lop</b> trong HOCSINH là khoá ngoài tham chiếu LOP.malop.',),('Ứng dụng đã gọi hệ QTCSDL thay họ; họ chỉ thao tác trên giao diện.',)],hper=2)
